uniform float uTime;

varying vec2 vUv;
varying vec3 vColor;
varying float vColorMode;
varying float vFade;
varying float vOpacity;
varying float vGrain;
varying float vEdgeGlow;

float random(vec2 st) {
  return fract(sin(dot(st, vec2(12.9898, 78.233))) * 43758.5453);
}

void main() {
  vec2 uv = vUv;

  // Distance from edge of the quad (0 at edge, 0.5 at center)
  float dx = min(uv.x, 1.0 - uv.x);
  float dy = min(uv.y, 1.0 - uv.y);
  float edgeDist = min(dx, dy);

  // Fill color
  vec3 fill = vColor;

  // Gradient mode: linear sweep from darker to brighter (branchless)
  vec3 gradFill = mix(fill * 0.5, fill * 1.5, uv.x);
  fill = mix(fill, gradFill, step(0.5, vColorMode));

  // Film grain — UV-based so it stays stable per-instance (no flicker)
  float grain = random(uv * 64.0 + floor(uTime * 0.5));
  fill += (grain - 0.5) * 0.08 * step(0.5, vGrain);

  // Edge glow: bright at borders, cubic falloff toward center (branchless)
  float t = clamp(edgeDist / 0.5, 0.0, 1.0);
  float glow = (1.0 - t) * (1.0 - t) * (1.0 - t);
  fill = mix(fill, fill * 1.8, glow * step(0.5, vEdgeGlow));

  gl_FragColor = vec4(fill, vOpacity * vFade);
}

