			float subLocalX = fract(subPixelX);

			// Sub-pixel gap (dark line between sub-pixels)
			float subGapX = smoothstep(0.0, 0.08, subLocalX) * smoothstep(1.0, 0.92, subLocalX);
			// Vertical gap at top and bottom of cell
			float subGapY = smoothstep(0.0, 0.06, localPos.y) * smoothstep(1.0, 0.94, localPos.y);
			float subGap = subGapX * subGapY;

			// Color per sub-pixel channel
			vec3 subColor = vec3(0.0);
			float brightness = max(color.r, max(color.g, color.b));

			if (subPixelIdx == 0) {
				subColor = vec3(color.r, color.r * 0.05, color.r * 0.02);
			} else if (subPixelIdx == 1) {
				subColor = vec3(color.g * 0.02, color.g, color.g * 0.05);
			} else {
				subColor = vec3(color.b * 0.05, color.b * 0.02, color.b);
			}

			// Blend: mostly show combined color, but let sub-pixels peek through on bright areas
			float subPixelStrength = 0.3 + brightness * 0.4;
			vec3 combined = mix(color.rgb, subColor, subPixelStrength);

			// Per-pixel manufacturing variance — subtle brightness jitter
			float pixelNoise = 0.92 + hash(cell) * 0.08;

			// Square LED shape with slight rounded edges
			vec2 edge = abs(localPos - 0.5);
			float maxEdge = max(edge.x, edge.y);
			float dot = smoothstep(0.48, 0.44, maxEdge);

			// Scanning refresh line — slow sweep down the screen
			float scanY = fract(uTime * 0.12);
			float scanDist = abs(vUv.y - scanY);
			float scanLine = 1.0 + smoothstep(0.06, 0.0, scanDist) * 0.7;

			vec3 result = combined * subGap * dot * pixelNoise * scanLine;

			// Glow bleed — bright pixels bleed into neighbors
			result += color.rgb * brightness * 0.08;

			gl_FragColor = vec4(result, 1.0);
		}

#version 300 es
void main() {
	vec2 p = vec2((gl_VertexID << 1) & 2, gl_VertexID & 2);
	gl_Position = vec4(p * 2.0 - 1.0, 0.0, 1.0);
}

#version 300 es
precision highp float;
precision highp int;
uniform vec2 uRes;
uniform float uAspect;
uniform float uTime;
uniform float uDistortion;
uniform float uSeed;
uniform vec3 uLab[4];
out vec4 outColor;

uint rotl(uint x, int k) { return (x << uint(k)) | (x >> uint(32 - k)); }
uint bjfinal(uint a, uint b, uint c) {
	c ^= b; c -= rotl(b, 14);
	a ^= c; a -= rotl(c, 11);
	b ^= a; b -= rotl(a, 25);
	c ^= b; c -= rotl(b, 16);
	a ^= c; a -= rotl(c, 4);
	b ^= a; b -= rotl(a, 14);
	c ^= b; c -= rotl(b, 24);
	return c;
}
uint hash3(int x, int y, int z) {
	uint seed = 0xdeadbeefu + (3u << 2) + 13u;
	return bjfinal(seed + uint(x), seed + uint(y), seed + uint(z));
}
float fade(float t) { return t * t * t * (t * (t * 6.0 - 15.0) + 10.0); }
float grad(uint hash, float x, float y, float z) {
	uint h = hash & 15u;
	float u = h < 8u ? x : y;
	float v = h < 4u ? y : ((h == 12u || h == 14u) ? x : z);
	return ((h & 1u) != 0u ? -u : u) + ((h & 2u) != 0u ? -v : v);
}
float noise(vec3 p) {
	int X = int(floor(p.x)); int Y = int(floor(p.y)); int Z = int(floor(p.z));
	float fx = p.x - float(X); float fy = p.y - float(Y); float fz = p.z - float(Z);
	float u = fade(fx); float v = fade(fy); float w = fade(fz);
	float v0 = grad(hash3(X, Y, Z), fx, fy, fz);
	float v1 = grad(hash3(X + 1, Y, Z), fx - 1.0, fy, fz);
	float v2 = grad(hash3(X, Y + 1, Z), fx, fy - 1.0, fz);
	float v3 = grad(hash3(X + 1, Y + 1, Z), fx - 1.0, fy - 1.0, fz);
	float v4 = grad(hash3(X, Y, Z + 1), fx, fy, fz - 1.0);
	float v5 = grad(hash3(X + 1, Y, Z + 1), fx - 1.0, fy, fz - 1.0);
	float v6 = grad(hash3(X, Y + 1, Z + 1), fx, fy - 1.0, fz - 1.0);
	float v7 = grad(hash3(X + 1, Y + 1, Z + 1), fx - 1.0, fy - 1.0, fz - 1.0);
	float s1 = 1.0 - u; float t1 = 1.0 - v; float r1 = 1.0 - w;
	float r = r1 * (t1 * (v0 * s1 + v1 * u) + v * (v2 * s1 + v3 * u))
		+ w * (t1 * (v4 * s1 + v5 * u) + v * (v6 * s1 + v7 * u));
	return 0.982 * r;
}
vec3 oklabToLinear(vec3 c) {
	float l = c.x + 0.3963377774 * c.y + 0.2158037573 * c.z;
	float m = c.x - 0.1055613458 * c.y - 0.0638541728 * c.z;
	float s = c.x - 0.0894841775 * c.y - 1.2914855480 * c.z;
	l = l * l * l; m = m * m * m; s = s * s * s;
	return vec3(
		4.0767416621 * l - 3.3077115913 * m + 0.2309699292 * s,
		-1.2684380046 * l + 2.6097574011 * m - 0.3413193965 * s,
		-0.0041960863 * l - 0.7034186147 * m + 1.7076147010 * s);
}

void main() {
	// The package's UVs run top-down; gl_FragCoord runs bottom-up.
	vec2 uv = gl_FragCoord.xy / uRes;
	uv.y = 1.0 - uv.y;
	float d = uDistortion;
	float t = uTime * 0.075;
	vec2 uv0 = uv - 0.5;
	float seedOff = uSeed * 0.17;
	float noiseVal = noise(vec3(uv0.x * 0.8 + t * 0.4, uv0.y * 0.8 - t * 0.25, seedOff));
	float angle = noiseVal * 12.566370614359172 * d;
	vec2 uvCorr = vec2(uv0.x, uv0.y / uAspect);
	float ca = cos(angle); float sa = sin(angle);
	float rotX = uvCorr.x * ca - uvCorr.y * sa;
	float rotY = (uvCorr.x * sa + uvCorr.y * ca) * uAspect;
	float ws = t * 2.0;
	float warpX = rotX + sin(rotY * 5.0 + ws) / 50.0 * d;
	float warpY = rotY + sin(warpX * 7.5 + ws) / 25.0 * d;
	vec3 wp1 = vec3(warpX * 2.0, warpY * 2.0, t * 0.5 + seedOff);
	float wx1 = noise(wp1 + vec3(5.2, 1.3, 0.0));
	float wy1 = noise(wp1 + vec3(1.7, 9.2, 0.0));
	float dw1X = warpX + wx1 * 0.25 * d;
	float dw1Y = warpY + wy1 * 0.25 * d;
	vec3 wp2 = vec3(dw1X * 1.5, dw1Y * 1.5, t * 0.3 + seedOff);
	float wx2 = noise(wp2 + vec3(8.3, 2.8, 0.0));
	float wy2 = noise(wp2 + vec3(3.1, 7.4, 0.0));
	float dw2X = dw1X + wx2 * 0.2 * d;
	float dw2Y = dw1Y + wy2 * 0.2 * d;
	float zoneNoise = noise(vec3(dw2X * 1.8, dw2Y * 1.8, t * 0.3 + seedOff));
	float edgeHardness = pow(wx1 * 0.5 + 0.5, 1.5);
	float edgeWidth = mix(0.5, 0.008, edgeHardness);
	float t1 = smoothstep(-edgeWidth, edgeWidth, zoneNoise);
	float t2 = smoothstep(-edgeWidth, edgeWidth, wy1);
	float foldMask1 = 1.0 - abs(t1 * 2.0 - 1.0);
	float foldMask2 = 1.0 - abs(t2 * 2.0 - 1.0);
	float foldHighlight = max(foldMask1, foldMask2) * edgeHardness;
	float surfaceLight = (wx2 * 0.5 + 0.5) * 0.12 + 0.94;
	float litScale = surfaceLight * (1.0 + foldHighlight * 0.35);
	vec3 lab = mix(mix(uLab[0], uLab[1], t1), mix(uLab[2], uLab[3], t1), t2);
	// The package works in linear Display P3 and writes those values to
	// the canvas as they are, which reads a touch softer than the sRGB
	// source colours. Matching that is what makes this look identical.
	vec3 p3 = mat3(
		0.8224621, 0.0331941, 0.0170826,
		0.177538, 0.9668058, 0.0723974,
		0.0, 0.0, 0.9105199) * oklabToLinear(lab);
	outColor = vec4(clamp(p3 * litScale, 0.0, 1.0), 1.0);
}

#version 300 es
precision highp float;
uniform sampler2D uTex;
uniform vec2 uStep;
uniform int uTaps;
uniform float uWeights[16];
out vec4 outColor;
void main() {
	vec2 size = vec2(textureSize(uTex, 0));
	vec2 uv = gl_FragCoord.xy / size;
	vec3 sum = texture(uTex, uv).rgb * uWeights[0];
	for (int i = 1; i < 16; i++) {
		if (i >= uTaps) break;
		vec2 o = uStep * float(i) / size;
		sum += (texture(uTex, uv + o).rgb + texture(uTex, uv - o).rgb) * uWeights[i];
	}
	outColor = vec4(sum, 1.0);
}

#version 300 es
precision highp float;
precision highp int;
uniform sampler2D uTex;
uniform vec2 uRes;
uniform float uAspect;
uniform vec3 uGrid;
uniform float uGrain;
out vec4 outColor;

float lineFilter(float p, float w, float n) {
	float a = p + w * 0.5;
	float b = p - w * 0.5;
	return (floor(a) + min(fract(a) * n, 1.0) - floor(b) - min(fract(b) * n, 1.0)) / (n * w);
}
float hash12(vec2 p) {
	uvec2 u = floatBitsToUint(p * vec2(141421356.0, 2718281828.0));
	return float((u.x ^ u.y) * 3141592653u) / 4294967295.0;
}
vec3 encode(vec3 c) {
	c = clamp(c, 0.0, 1.0);
	return mix(c * 12.92, 1.055 * pow(c, vec3(1.0 / 2.4)) - 0.055, step(0.0031308, c));
}

void main() {
	vec2 uv = gl_FragCoord.xy / uRes;
	vec3 c = texture(uTex, uv).rgb;
	if (uGrid.z > 0.0) {
		// Grid flips the package's top-down UVs, so it counts bottom-up.
		vec2 gridUV = uv * vec2(uAspect, 1.0) * uGrid.x;
		float lineWidth = max(uGrid.y * 0.01, 1e-4);
		float n = 1.0 / (lineWidth * 2.0);
		vec2 p = gridUV + lineWidth;
		vec2 dx = dFdx(p);
		vec2 dy = dFdy(p);
		float wx = max(max(abs(dx.x), abs(dy.x)), 1e-5);
		float wy = max(max(abs(dx.y), abs(dy.y)), 1e-5);
		float gap = (1.0 - lineFilter(p.x, wx, n)) * (1.0 - lineFilter(p.y, wy, n));
		c *= 1.0 - (1.0 - gap) * uGrid.z;
	}
	if (uGrain > 0.0) {
		float grain = hash12(gl_FragCoord.xy) * 2.0 - 1.0;
		float brightness = clamp(dot(c, vec3(0.2126, 0.7152, 0.0722)), 0.0, 1.0);
		c += grain * pow(1.0 - brightness + 1e-6, 2.0) * uGrain * 0.1;
	}
	outColor = vec4(encode(c), 1.0);
}
